SELECT c1.name, AVG(CASE WHEN EXISTS (SELECT 1 FROM returns r WHERE r.order_item_id = oi.order_item_id) THEN 1.0 ELSE 0.0 END) FROM order_items oi JOIN orders o USING (order_id) JOIN product_variants v USING (variant_id) JOIN products p USING (product_id) JOIN categories c3 ON c3.category_id = p.category_id JOIN categories c2 ON c2.category_id = c3.parent_category_id JOIN categories c1 ON c1.category_id = c2.parent_category_id WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'returned') AND o.order_at >= TIMESTAMP '2025-01-01 00:00:00' AND o.order_at < TIMESTAMP '2026-01-01 00:00:00' AND c1.name IN ('Fashion', 'Electronics') GROUP BY 1
